result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/aging.py", "content": """"Aging-bucket logic for open invoice balances.

Bucketing is by days past the invoice date, computed as
(as_of - invoice_date).days against the documented cutoffs:

    current : 0-30 days
    31-60   : 31-60 days
    61-90   : 61-90 days
    90+     : 91+ days

So an invoice exactly 31 days old lands in "31-60", exactly 61 days in
"61-90", and exactly 91 days in "90+". Open amount is always
amount - payment using Decimal arithmetic.
"""

from datetime import date
from decimal import Decimal

# Bucket label -> (inclusive lower bound, inclusive upper bound) in days.
BUCKET_RANGES = {
    "current": (0, 30),
    "31-60": (31, 60),
    "61-90": (61, 90),
    "90+": (91, None),
}
BUCKETS = list(BUCKET_RANGES)


def parse_date(text: str) -> date:
    return date.fromisoformat(text)


def days_past(invoice_date: str | date, as_of: str | date) -> int:
    """Whole days between the invoice date and the as-of date."""
    inv = parse_date(invoice_date) if isinstance(invoice_date, str) else invoice_date
    ref = parse_date(as_of) if isinstance(as_of, str) else as_of
    return (ref - inv).days


def bucket_for(days: int) -> str:
    """Return the bucket label for an invoice that is `days` days old."""
    if days < BUCKET_RANGES["current"][0]:
        raise ValueError(f"negative age not allowed: {days}")
    for label, (low, high) in BUCKET_RANGES.items():
        if days >= low and (high is None or days <= high):
            return label
    raise ValueError(f"unclassifiable age: {days}")


def open_amount(invoice: dict) -> Decimal:
    """Open (unpaid) portion of an invoice."""
    return Decimal(invoice["amount"]) - Decimal(invoice["payment"])


def customer_aging(customer: dict, as_of: str | date) -> dict[str, Decimal]:
    """Bucket totals for one customer's open balances."""
    totals = {label: Decimal("0.00") for label in BUCKETS}
    for invoice in customer["invoices"]:
        open_amt = open_amount(invoice)
        if open_amt <= 0:
            continue  # fully paid invoices carry no open balance
        totals[bucket_for(days_past(invoice["date"], as_of))] += open_amt
    return totals


def global_aging(customers: list[dict], as_of: str | date) -> dict[str, Decimal]:
    """Bucket totals across all customers."""
    totals = {label: Decimal("0.00") for label in BUCKETS}
    for customer in customers:
        for label, value in customer_aging(customer, as_of).items():
            totals[label] += value
    return totals
